<?php
/** Proof — the activity server: a ticket's timeline in facts, who touched it, what a person or every agent did, a queue's feed, configuration changes, the guarded search; and that the trail never carries a body, a token, a secure link or another requester's address. */
require __DIR__ . '/lib.php';
$F = dated(); $W = world(); $T = $F['tickets']; $IT = $F['it'];
$owner = as_member(1); $marco = as_member(27); $lena = as_member(28); $priya = as_member(26);
$sorted = function (array $a) { sort($a); return $a; };
$t = mkticket(requester_of_member(26), $IT, 'SMOKE p4 activity ticket');
$since = last_activity_id();
echo "1. Make some history through the application's own handlers\n";
[$c, $b] = act($marco, '/tickets/note.php', ['ticket' => $t, 'body' => 'SMOKE p4 internal note ' . str_repeat('padding ', 40) . 'SECRETWORDS']);
ok($c === 200, 'Marco adds a note');
[$c, $b] = act($marco, '/tickets/reply.php', ['ticket' => $t, 'body' => 'SMOKE p4 public reply ' . str_repeat('padding ', 40) . 'SECRETWORDS']);
ok($c === 200, 'Marco replies');
[$c, $b] = act($marco, '/tickets/assign.php', ['ticket' => $t, 'assignee' => 27]);
ok($c === 200, 'Marco assigns it to himself');
[$c, $b] = act($marco, '/tickets/transition.php', ['ticket' => $t, 'status' => 'solved', 'resolution_code' => 'resolved']);
ok($c === 200, 'Marco solves it');
page($marco, '/tickets/' . $t);
echo "2. ticket_history\n";
$d = tdata(27, 'ticket_history', ['ticket_id' => $t], ACT);
$actions = array_column($d['events'], 'action');
ok($d['ticket']['number'] === num_of($t) && array_slice($actions, 0, 0) === [] && in_array('ticket.note', $actions) && in_array('ticket.reply', $actions) && in_array('ticket.assign', $actions) && in_array('ticket.transition', $actions) && !in_array('screen.view', $actions), 'Marco: the note, the reply, the assignment and the transition — no screen views');
$tr = array_values(array_filter($d['events'], fn ($e) => $e['action'] === 'ticket.transition'))[0];
ok($tr['after']['status'] === 'solved' && ($tr['after']['resolution_code'] ?? '') === 'resolved' && $tr['actor_name'] === 'SMOKE Marco' && isset($tr['occurred_at_local']), 'the transition: status to solved with the code, by whom, when');
ok($d['events'][0]['occurred_at'] <= end($d['events'])['occurred_at'], 'oldest first');
$d2 = tdata(27, 'ticket_history', ['number' => num_of($t), 'order' => 'newest', 'limit' => 2], ACT);
ok(count($d2['events']) === 2 && $d2['events'][0]['occurred_at'] >= $d2['events'][1]['occurred_at'], 'by number, newest first, limited');
$d3 = tdata(26, 'ticket_history', ['ticket_id' => $t], ACT);
$a3 = array_column($d3['events'], 'action');
ok(!isset($d3['error']) && in_array('ticket.reply', $a3) && !in_array('ticket.note', $a3) && !in_array('ticket.dispatch', $a3), 'Priya on her own ticket: the reply and the status, never the internal note');
ok(tool(26, 'ticket_history', ['ticket_id' => $T['it5']], ACT)['error'] && tool(27, 'ticket_history', [], ACT)['error'], 'a ticket she may not see: refused; no id: asked which');
$all = json_encode([$d, $d3, tdata(27, 'actor_timeline', ['period' => 'today'], ACT), tdata(28, 'queue_activity', ['queue_id' => $IT], ACT)]);
ok(!str_contains($all, 'SECRETWORDS') && str_contains($all, 'SMOKE p4 public reply'), 'a message body is never in a row — at most the 200-character excerpt (the end of a long reply is in none)');
ok(!preg_match('/[a-f0-9]{48}/', $all) && !str_contains($all, 'token_hash'), 'and no secure token, no token value');
echo "3. who_touched, actor_timeline\n";
$d = tdata(27, 'who_touched', ['ticket_id' => $t], ACT);
ok($d['last']['action'] === 'ticket.transition' && count($d['everyone']) >= 1 && $d['everyone'][0]['actor_name'] === 'SMOKE Marco' && $d['everyone'][0]['actions'] >= 4, 'who_touched: last was the transition; Marco did four or more things');
ok(tool(26, 'who_touched', ['ticket_id' => $T['it5']], ACT)['error'], 'a ticket she may not see: refused');
$d = tdata(27, 'actor_timeline', ['period' => 'today'], ACT);
ok(count($d['events']) >= 4 && !array_filter($d['events'], fn ($e) => $e['actor_member_id'] !== 27) && array_column($d['by_action'], 'n', 'action')['ticket.reply'] >= 1, 'actor_timeline: Marco\'s own day, counted by action');
$d = tdata(27, 'actor_timeline', ['period' => 'today', 'action' => 'screen.view'], ACT);
$sv = array_values(array_filter($d['events'], fn ($e) => $e['ticket_id'] === $t));
ok(count($sv) >= 1 && $sv[0]['ticket_number'] === num_of($t), 'screen.view with a ticket: which tickets he looked at');
$d = tdata(27, 'actor_timeline', ['period' => 'today', 'action' => 'ticket.'], ACT);
ok(count($d['events']) >= 4 && !array_filter($d['events'], fn ($e) => !str_starts_with($e['action'], 'ticket.')), 'an action prefix (ticket.)');
$d = tdata(27, 'actor_timeline', ['member_id' => 28, 'period' => 'last_30_days'], ACT);
ok(!array_filter($d['events'], fn ($e) => $e['actor_member_id'] !== 28), "another person's timeline: only rows Marco's reach shows, all of them Lena's");
$d = tdata(26, 'actor_timeline', ['period' => 'today'], ACT);
ok(!array_filter($d['events'], fn ($e) => $e['actor_member_id'] !== 26), 'Priya reads her own');
q("INSERT INTO activity_log (actor_member_id, source, action, entity_type, entity_id, ticket_id, queue_id, after) VALUES (40, 'agent', 'ticket.reply', 'ticket', :t, :t, :q, '{\"excerpt\":\"SMOKE p4 agent did it\"}')", ['t' => $T['it5'], 'q' => $IT]);
$d = tdata(28, 'actor_timeline', ['actor_kind' => 'agent', 'period' => 'today'], ACT);
ok(count($d['events']) >= 1 && !array_filter($d['events'], fn ($e) => $e['actor_member_id'] !== 40), 'actor_kind=agent: what every agent did today');
ok(tool(28, 'actor_timeline', ['period' => 'today', 'from' => '2026-02-01', 'to' => '2026-01-01'], ACT)['error'], 'a backwards period: refused');
echo "4. queue_activity, config_change_log\n";
$d = tdata(28, 'queue_activity', ['queue_id' => $IT, 'period' => 'today'], ACT);
$people = array_column($d['by_person'], 'n', 'actor_name');
ok(($people['SMOKE Marco'] ?? 0) >= 4 && array_column($d['by_action'], 'n', 'action')['ticket.transition'] >= 1 && !array_filter($d['events'], fn ($e) => $e['queue_id'] !== $IT), 'queue_activity: IT today by action and by person');
ok(tool(26, 'queue_activity', ['queue_id' => $IT], ACT)['error'], 'a requester: refused (a queue holder\'s tool)');
$d = tdata(27, 'queue_activity', ['queue_id' => $F['fac'], 'period' => 'last_30_days'], ACT);
ok($d['events'] === [] && $d['by_action'] === [], "another queue's feed is empty to its non-holder");
act($owner, '/settings/queues/save.php', ['queue' => $IT, 'description' => 'SMOKE p4 config change']);
$d = tdata(1, 'config_change_log', ['period' => 'today'], ACT);
$acts = array_column($d['changes'], 'action');
ok(in_array('queue.update', $acts) && !in_array('ticket.reply', $acts) && !in_array('screen.view', $acts), 'config_change_log: the queue update, and none of the ticket traffic');
$q = array_values(array_filter($d['changes'], fn ($e) => $e['action'] === 'queue.update'))[0];
ok(isset($q['before']) && isset($q['after']) && str_contains(json_encode($q['after']), 'SMOKE p4 config change'), 'with before and after');
$d = tdata(1, 'config_change_log', ['period' => 'today', 'entity_type' => 'queue'], ACT);
ok(count($d['changes']) >= 1 && !array_filter($d['changes'], fn ($e) => $e['entity_type'] !== 'queue'), 'entity_type=queue');
ok(!array_filter(tdata(26, 'config_change_log', ['period' => 'today'], ACT)['changes'], fn ($e) => $e['actor_member_id'] !== 26), 'a requester sees no one else\'s configuration changes');
echo "5. activity_search\n";
$d = tdata(27, 'activity_search', ['sql' => "select action, count(*) as n from mcp_activity_log where ticket_id = $t group by 1 order by 1"], ACT);
ok(is_array($d) && count($d) >= 4 && isset($d[0]['action']), 'a SELECT over mcp_activity_log');
$d = tdata(27, 'activity_search', ['sql' => "select t.number, count(*) as n from mcp_activity_log l join mcp_tickets t on t.ticket_id = l.ticket_id where l.ticket_id = $t group by 1"], ACT);
ok(count($d) === 1 && $d[0]['number'] === num_of($t), 'joined to the fact views (mcp_tickets)');
foreach (['delete from activity_log' => 'Only a single SELECT', "select * from activity_log" => 'Query failed', "select * from mcp_requesters" => 'Query failed', "select set_config('app.member_id','1',true)" => 'set_config', 'select 1; select 2' => 'Only one statement'] as $sql => $why) {
    $r = tool(27, 'activity_search', ['sql' => $sql], ACT);
    ok($r['error'] || str_contains($r['text'], $why), 'activity_search refuses: ' . substr($sql, 0, 44));
}
$d = tdata(26, 'activity_search', ['sql' => 'select count(*) as n from mcp_activity_log'], ACT);
ok($d[0]['n'] === count(sql_as(26, 'select 1 from mcp_activity_log')), 'scoped to the caller');
finish();
